// What a flow can see of the process that runs it. On the ZIPP VM in a worker
// thread every entry is 'undefined' and the token is unreachable; in-thread on
// Node this read ['object', 'undefined', 'function', 'object'] and the token itself.
return {
  types: [typeof process, typeof require, typeof Buffer, typeof globalThis.__TAURI__],
  token: typeof process === 'undefined' ? 'no-process' : process.env.OAIY_SERVER_TOKEN,
};
